<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigEnableRegisterUsersAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigEnableRegisterUsersAccessor trait.
 *
 * Covers null default, string/VO assignment via withEnableRegisterUsers,
 * getEnableRegisterUsers/enableRegisterUsers accessors, and isEnableRegisterUsersChanged with/without original.
 */
class TenantConfigEnableRegisterUsersAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withEnableRegisterUsers creates a new instance with the EnableRegisterUsers set
     * from a string value, and getEnableRegisterUsers returns the primitive string.
     */
    public function testWithEnableRegisterUsersFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigEnableRegisterUsersAccessorUnitTest();

        // Act
        $result = $holder->withEnableRegisterUsers(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isEnableRegisterUsers());
    }
    /**
     * Asserts that withenableRegisterUsers has access to the value object
     * from a string value, and getEnableRegisterUsers returns the primitive string.
     */
    public function testWithEnableRegisterUsersFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigEnableRegisterUsersAccessorUnitTest();

        // Act
        $result = $holder->withEnableRegisterUsers(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->enableRegisterUsers()->value());
    }
    public function testChangedEnableRegisterUsers(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigEnableRegisterUsersAccessorUnitTest();
        $original = $holder->withEnableRegisterUsers(true);
        $same = $holder->withEnableRegisterUsers(true);
        $modified = $holder->withEnableRegisterUsers(false);

        // Act
        $unchanged = $holder->isEnableRegisterUsersChanged();
        $withSame = $original->isEnableRegisterUsersChanged($same);
        $withDiferent = $original->isEnableRegisterUsersChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigEnableRegisterUsersAccessorUnitTest
{
    use TenantConfigEnableRegisterUsersAccessor;
}
